    ll ans = 0;
    ll half_N_1 = power(inv2, N-1, MOD); // (1/2)^(N-1)

    for (int v = 1; v <= N; v++) {
        // components: children subtrees and upward component
        // P(at most 1 component has black)
        ll prod = half_N_1; // (1/2)^(N-1)
        ll sum_only_i = 0;

        for (int e = head[v]; e; e = nxt[e]) {
            int u = to[e];
            if (u == parent[v]) continue;
            int ci = subtree[u];
            // (1 - (1/2)^ci) * (1/2)^(N-1-ci)
            ll term = (1 - power(inv2, ci, MOD) + MOD) % MOD * power(inv2, N-1-ci, MOD) % MOD;
            sum_only_i = (sum_only_i + term) % MOD;
        }
        // upward component size = N - subtree[v]
        if (parent[v] != 0) {
            int ci = N - subtree[v];
            ll term = (1 - power(inv2, ci, MOD) + MOD) % MOD * power(inv2, N-1-ci, MOD) % MOD;
            sum_only_i = (sum_only_i + term) % MOD;
        }

        ll at_most_1 = (prod + sum_only_i) % MOD;
        ll prob = inv2 % MOD * ((1 - at_most_1 + MOD) % MOD) % MOD;
        ans = (ans + prob) % MOD;
    }

    printf("%lld\n", ans);
    return 0;
}

