#include <stdlib.h>

#define MOD 1000000007LL

typedef long long ll;

typedef struct Edge {
    int to, next;
} Edge;

static ll modpow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    if (N == 1) {
        /* Single vertex can never be a white internal vertex of the minimal
           subtree containing all black vertices. */
        printf("0\n");
        return 0;
    }

    Edge *edges = (Edge *)malloc(sizeof(Edge) * 2 * (N - 1));
    int *head = (int *)malloc(sizeof(int) * (N + 1));
    int *deg = (int *)calloc(N + 1, sizeof(int));
    int *parent = (int *)malloc(sizeof(int) * (N + 1));
    int *order = (int *)malloc(sizeof(int) * N);
    int *sub = (int *)malloc(sizeof(int) * (N + 1));

    for (int i = 1; i <= N; i++) head[i] = -1;

    int ecnt = 0;
    for (int i = 0; i < N - 1; i++) {
        int u, v;
        scanf("%d %d", &u, &v);
        edges[ecnt].to = v; edges[ecnt].next = head[u]; head[u] = ecnt++;
        edges[ecnt].to = u; edges[ecnt].next = head[v]; head[v] = ecnt++;
        deg[u]++;
        deg[v]++;
    }

    /* Root the tree at 1 and compute parent/order */
    int *queue = (int *)malloc(sizeof(int) * N);
    int qh = 0, qt = 0, ordsz = 0;
    queue[qt++] = 1;
    parent[1] = 0;
    while (qh < qt) {
        int v = queue[qh++];
        order[ordsz++] = v;
        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            if (to == parent[v]) continue;
            parent[to] = v;
            queue[qt++] = to;
        }
    }

    /* Subtree sizes */
    for (int i = 1; i <= N; i++) sub[i] = 1;
    for (int i = N - 1; i > 0; i--) {
        int v = order[i];
        sub[parent[v]] += sub[v];
    }

    /* Precompute powers of 1/2 */
    ll inv2 = (MOD + 1) / 2; /* inverse of 2 modulo MOD */
    ll *powInv2 = (ll *)malloc(sizeof(ll) * (N + 1));
    powInv2[0] = 1;
    for (int i = 1; i <= N; i++) powInv2[i] = (powInv2[i - 1] * inv2) % MOD;

    ll ans = 0;

    /* For each vertex v, probability that v is white and belongs to the Steiner
       tree of black vertices:
         P = (1/2) * [1 - P(all black vertices lie in one component of T-v)]
       Let component sizes after removing v be c1, c2, ..., ck.
       Then:
         P(all black in one component) = sum_i 2^{- (N - c_i)} - (k-1) * 2^{-N}
       because the all-white coloring is counted in every component.
       So contribution of v:
         (1/2) * (1 - sum_i 2^{-(N-c_i)} + (k-1) * 2^{-N})
       Leaves have zero contribution automatically.
    */
    for (int v = 1; v <= N; v++) {
        if (deg[v] <= 1) continue; /* cannot be a white hole */

        ll sum = 0;
        int comps = 0;

        for (int e = head[v]; e != -1; e = edges[e].next) {
            int to = edges[e].to;
            int csz;
            if (to == parent[v]) csz = N - sub[v];
            else csz = sub[to];
            sum += powInv2[N - csz];
            if (sum >= MOD) sum -= MOD;
            comps++;
        }

        ll p_one = sum - ((ll)(comps - 1) * powInv2[N]) % MOD;
        if (p_one < 0) p_one += MOD;

        ll p_in = (1 - p_one) % MOD;
        if (p_in < 0) p_in += MOD;
        p_in = (p_in * inv2) % MOD; /* multiply by P(v is white)=1/2 */

        ans += p_in;
        if (ans >= MOD) ans -= MOD;
    }

    printf("%lld\n", ans);

    free(edges);
    free(head);
    free(deg);
    free(parent);
    free(order);
    free(sub);
    free(queue);
    free(powInv2);

    return 0;
}

