int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<vector<int>> g(N + 1);
    for (int i = 0; i < N - 1; ++i) {
        int u, v;
        cin >> u >> v;
        g[u].push_back(v);
        g[v].push_back(u);
    }

    if (N == 1) {
        // Single vertex can never be a white vertex inside the minimal subtree
        // containing all black vertices.
        cout << 0 << '\n';
        return 0;
    }

    vector<int> parent(N + 1, 0), order;
    order.reserve(N);
    stack<int> st;
    st.push(1);
    parent[1] = -1;

    while (!st.empty()) {
        int u = st.top();
        st.pop();
        order.push_back(u);
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            parent[v] = u;
            st.push(v);
        }
    }

    vector<int> sz(N + 1, 1);
    for (int i = N - 1; i >= 0; --i) {
        int u = order[i];
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            sz[u] += sz[v];
        }
    }

    long long inv2 = (MOD + 1) / 2;
    vector<long long> powInv2(N + 1, 1);
    for (int i = 1; i <= N; ++i) powInv2[i] = powInv2[i - 1] * inv2 % MOD;

    long long ans = 0;

    for (int u = 1; u <= N; ++u) {
        vector<int> comps;
        int sumChild = 0;
        for (int v : g[u]) {
            if (v == parent[u]) continue;
            comps.push_back(sz[v]);
            sumChild += sz[v];
        }
        if (parent[u] != -1) {
            comps.push_back(N - 1 - sumChild);
        }

        // Let component sizes after removing u be c1, c2, ..., ck.
        // For u to belong to the Steiner tree of black vertices while u is white:
        // there must be black vertices in at least two different components.
        //
        // Probability(no black anywhere) = 2^{-(N-1)}
        // Probability(all black vertices lie in a single chosen component i) =
        //   2^{-(N-1-ci)} * 2^{-ci} summed over all subsets in ci? Simpler:
        //   all vertices outside component i are white => 2^{-(N-1-ci)}
        //   vertices inside component i arbitrary => already includes empty/all white
        // So probability(all black vertices lie in component i) = 2^{-(N-1-ci)}.
        //
        // Using inclusion-exclusion over the event "black vertices appear in at least two components":
        // P = 1 - sum_i 2^{-(N-1-ci)} + (k-1)*2^{-(N-1)}
        // Then multiply by P(u is white)=1/2.
        long long sumSingle = 0;
        for (int c : comps) {
            sumSingle += powInv2[N - 1 - c];
            if (sumSingle >= MOD) sumSingle -= MOD;
        }

        long long pTwoOrMore = (1 - sumSingle + (long long)(comps.size() - 1) * powInv2[N - 1]) % MOD;
        if (pTwoOrMore < 0) pTwoOrMore += MOD;

        ans = (ans + inv2 * pTwoOrMore) % MOD;
    }

    cout << ans % MOD << '\n';
    return 0;
}

