            g[v].add(u);
        }

        // pow2[k] = 2^k mod MOD
        long[] pow2 = new long[n + 2];
        pow2[0] = 1;
        for (int i = 1; i <= n + 1; i++) pow2[i] = pow2[i - 1] * 2 % MOD;

        long invPow2n = modInv(pow2[n]);
        long expected = 0;

        // For each vertex, compute probability it's white and in S
        for (int u = 0; u < n; u++) {
            int deg = g[u].size();
            long[] compSizes = new long[deg];
            boolean[] visited = new boolean[n];
            visited[u] = true;
            for (int i = 0; i < deg; i++) {
                compSizes[i] = dfsSize(g, visited, g[u].get(i));
            }

            long probWhiteInS = 0;
            // probability white = 1/2
            // probability black exists in at least 2 components = 1 - (prob in 0 or 1 component)
            long probZeroOrOne = 0;
            // prob zero components = 2^{-n}
            probZeroOrOne = pow2[0] * modInv(pow2[n]) % MOD; // (1/2^n)
            // prob exactly one component: sum over comp j of (1/2)^{size_j} * (1/2)^{n - size_j} = sum size_j * (1/2^n)
            // Actually: P(only comp j has black) = (1/2)^{size_j} * (1/2)^{n - size_j} = 1/2^n
            probZeroOrOne = (probZeroOrOne + deg * modInv(pow2[n])) % MOD;

            long probAtLeastTwo = (1 - probZeroOrOne + MOD) % MOD;
            long probWhite = modInv(2);
            probWhiteInS = probWhite * probAtLeastTwo % MOD;
            expected = (expected + probWhiteInS) % MOD;
        }

        System.out.println(expected);
    }

    static int dfsSize(List<Integer>[] g, boolean[] visited, int u) {
        visited[u] = true;
        int size = 1;
        for (int v : g[u]) {
            if (!visited[v]) {
                size += dfsSize(g, visited, v);
            }
        }
        return size;
    }

    static long modInv(long a) {
        return modPow(a, MOD - 2);
    }

    static long modPow(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}

