            for (int v : g[u]) {
                if (v == parent[u]) continue;
                parent[v] = u;
                depth[v] = depth[u] + 1;
                stack[top++] = v;
            }
        }

        int[] sub = new int[N + 1];
        for (int i = N - 1; i >= 0; i--) {
            int u = order[i];
            sub[u] = 1;
            for (int v : g[u]) {
                if (v == parent[u]) continue;
                sub[u] += sub[v];
            }
        }

        long[] pow2inv = new long[N + 1];
        pow2inv[0] = 1;
        for (int i = 1; i <= N; i++) pow2inv[i] = pow2inv[i - 1] * INV2 % MOD;

        long ans = 0;

        for (int v = 1; v <= N; v++) {
            int deg = g[v].size();
            int[] comps = new int[deg];
            int p = 0;

            for (int to : g[v]) {
                if (to == parent[v]) comps[p++] = N - sub[v];
                else comps[p++] = sub[to];
            }

            long sumNoBlack = 0;
            for (int s : comps) {
                sumNoBlack += pow2inv[s];
                if (sumNoBlack >= MOD) sumNoBlack -= MOD;
            }

            // Probability vertex v belongs to Steiner tree of black vertices:
            // P(in S) = 1 - P(no black at all) - P(all black vertices lie in one component after removing v)
            //          = 1 - 2^-N - sum(2^-N * (2^{size_i} - 1))
            //          = 1 - sum(2^{-(N-size_i)})
            long pin = 1 - sumNoBlack;
            if (pin < 0) pin += MOD;

            // Need v white as well, independent with probability 1/2
            long contrib = pin * INV2 % MOD;
            ans += contrib;
            if (ans >= MOD) ans -= MOD;
        }

        System.out.println(ans % MOD);
    }
}

import sys
sys.setrecursionlimit(300000)
MOD = 10**9 + 7

def modinv(x):
    return pow(x, MOD - 2, MOD)

INV2 = modinv(2)

def solve():
    input = sys.stdin.readline
    N = int(input())
    g = [[] for _ in range(N)]
    for _ in range(N - 1):
        u, v = map(int, input().split())
        g[u].append(v)
        g[v].append(u)

    pow2 = [1] * (N + 1)
    inv_pow2 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow2[i] = pow2[i-1] * 2 % MOD
        inv_pow2[i] = inv_pow2[i-1] * INV2 % MOD

    size = [0] * N
    parent = [-1] * N
    order = [0]
    for v in order:
        for to in g[v]:
            if to != parent[v]:
                parent[to] = v
                order.append(to)
    for v in reversed(order):
        size[v] = 1
        for to in g[v]:
            if to != parent[v]:
                size[v] += size[to]

    ans = 0
    all_black_prob = inv_pow2[N]
    for v in range(N):
        comps = []
        for to in g[v]:
            if to == parent[v]:
                comps.append(N - size[v])
            else:
                comps.append(size[to])
        prob_all_in_one = 0
        for c in comps:
            prob_all_in_one = (prob_all_in_one + inv_pow2[c]) % MOD
        prob_all_in_one = (prob_all_in_one - (N - 1) * all_black_prob) % MOD
        prob_white_in_sub = INV2 * ((1 - prob_all_in_one - all_black_prob) % MOD) % MOD
        ans = (ans + prob_white_in_sub) % MOD

    print(ans % MOD)

if __name__ == "__main__":
    solve()
